import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from 'react';
import { useColorScheme } from 'react-native';
import {
  readSystemAccessibility,
  subscribeToSystemAccessibility,
  type GlassyUiPreferences,
  type GlassyUiTheme,
} from './lib/preferences';
import { GLASS_COLORS } from './lib/tokens';

type PreferenceState = Required<GlassyUiPreferences>;

type PreferenceContextValue = {
  preferences: PreferenceState;
  setPreferences: (prefs: Partial<GlassyUiPreferences>) => void;
};

const PreferencesContext = createContext<PreferenceContextValue | null>(null);

function ignorePreferences() {}

/** The device's appearance and accessibility settings, as glass preferences. */
function useSystemPreferences(): PreferenceState {
  const scheme = useColorScheme();

  const accessibility = useSyncExternalStore(
    subscribeToSystemAccessibility,
    readSystemAccessibility,
    readSystemAccessibility,
  );

  return useMemo(
    () => ({
      theme: scheme === 'light' ? 'light' : 'dark',
      mode: 'clear',
      reduceMotion: accessibility.reduceMotion,
      reduceTransparency: accessibility.reduceTransparency,
    }),
    [accessibility, scheme],
  );
}

/**
 * Holds the glass preferences every component follows. It starts from the device's appearance,
 * Reduce Motion and Reduce Transparency settings; `defaultTheme` overrides the appearance until
 * the app sets a theme. Choices made with `setPreferences` last while the provider is mounted;
 * persist them in your app's own storage if they should survive a restart.
 */
export function GlassProvider({
  children,
  defaultTheme,
}: {
  children: ReactNode;
  defaultTheme?: GlassyUiTheme;
}) {
  const system = useSystemPreferences();
  const [explicit, setExplicit] = useState<GlassyUiPreferences>({});

  const preferences = useMemo(() => {
    const merged: PreferenceState = { ...system, ...explicit };

    if (defaultTheme && explicit.theme === undefined) merged.theme = defaultTheme;

    return merged;
  }, [defaultTheme, explicit, system]);

  const setPreferences = useCallback((next: Partial<GlassyUiPreferences>) => {
    setExplicit((previous) => ({ ...previous, ...next }));
  }, []);

  const value = useMemo(() => ({ preferences, setPreferences }), [preferences, setPreferences]);

  return <PreferencesContext.Provider value={value}>{children}</PreferencesContext.Provider>;
}

export const PreferencesProvider = GlassProvider;

/** The provider's preferences, or the device's own settings when no provider is mounted. */
export function useOptionalPreferences(): PreferenceContextValue {
  const context = useContext(PreferencesContext);
  const system = useSystemPreferences();

  return context ?? { preferences: system, setPreferences: ignorePreferences };
}

export function usePreferences() {
  const context = useContext(PreferencesContext);

  if (!context) {
    throw new Error('usePreferences must be used within GlassProvider');
  }

  return context;
}

/** The colours for the current theme, with the preferences they came from. */
export function useGlassTheme() {
  const { preferences } = useOptionalPreferences();

  return { colors: GLASS_COLORS[preferences.theme], preferences };
}

import { AccessibilityInfo, Platform } from 'react-native';

export type GlassyUiMode = 'clear' | 'tinted';

export type GlassyUiTheme = 'light' | 'dark';

export interface GlassyUiPreferences {
  theme?: GlassyUiTheme;
  /** Clear glass shows more of what lies behind it; tinted glass holds a denser frost. */
  mode?: GlassyUiMode;
  reduceTransparency?: boolean;
  reduceMotion?: boolean;
}

export type SystemAccessibility = {
  reduceMotion: boolean;
  reduceTransparency: boolean;
};

type Subscription = { remove: () => void };

// The system's accessibility settings, read once and shared by every glass component.
let snapshot: SystemAccessibility = { reduceMotion: false, reduceTransparency: false };

const listeners = new Set<() => void>();

let subscriptions: Subscription[] = [];

function update(next: Partial<SystemAccessibility>) {
  const merged = { ...snapshot, ...next };

  if (
    merged.reduceMotion === snapshot.reduceMotion &&
    merged.reduceTransparency === snapshot.reduceTransparency
  ) {
    return;
  }

  snapshot = merged;
  listeners.forEach((listener) => listener());
}

function warnReadFailure(cause: Error) {
  console.warn('Glassy UI could not read an accessibility setting', cause);
}

function startListening() {
  AccessibilityInfo.isReduceMotionEnabled()
    .then((reduceMotion) => update({ reduceMotion }))
    .catch(warnReadFailure);

  subscriptions.push(
    AccessibilityInfo.addEventListener('reduceMotionChanged', (reduceMotion) =>
      update({ reduceMotion }),
    ),
  );

  if (Platform.OS === 'ios') {
    AccessibilityInfo.isReduceTransparencyEnabled()
      .then((reduceTransparency) => update({ reduceTransparency }))
      .catch(warnReadFailure);

    subscriptions.push(
      AccessibilityInfo.addEventListener('reduceTransparencyChanged', (reduceTransparency) =>
        update({ reduceTransparency }),
      ),
    );
  }

  // React Native for Web has no reduce-transparency event; the browser reports it directly.
  if (Platform.OS === 'web' && window.matchMedia) {
    const query = window.matchMedia('(prefers-reduced-transparency: reduce)');
    const handleChange = () => update({ reduceTransparency: query.matches });

    update({ reduceTransparency: query.matches });
    query.addEventListener('change', handleChange);
    subscriptions.push({ remove: () => query.removeEventListener('change', handleChange) });
  }
}

export function subscribeToSystemAccessibility(listener: () => void) {
  listeners.add(listener);

  if (listeners.size === 1) startListening();

  return () => {
    listeners.delete(listener);

    if (listeners.size > 0) return;

    subscriptions.forEach((subscription) => subscription.remove());
    subscriptions = [];
  };
}

export function readSystemAccessibility() {
  return snapshot;
}

import { Platform } from 'react-native';
import type { GlassyUiTheme } from './preferences';

export type GlassTone = 'neutral' | 'blue' | 'green' | 'orange' | 'red' | 'purple';

export type GlassColors = {
  /** Selection, active controls and the prominent button. */
  accent: string;
  accentForeground: string;
  border: string;
  /** The resting fill of fields and unselected controls. */
  controlSurface: string;
  focusRing: string;
  foreground: string;
  /** Extra frost over blurred glass, for clear and tinted glass. */
  glassFill: Record<'clear' | 'tinted', string>;
  invalid: string;
  knob: string;
  mutedForeground: string;
  /** Where glass cannot be drawn: Reduce Transparency. */
  opaqueSurface: string;
  /** Floating layers that must hold 4.5:1 text over any backdrop. */
  overlaySurface: string;
  /** The hairline round a glass edge, and the light it catches along the top. */
  rim: string;
  rimHighlight: string;
  scrim: string;
  shadow: string;
  shadowRaised: string;
  tones: Record<GlassTone, string>;
  track: string;
};

/** Glass stays neutral. Blue marks actions and selection; the tones mark status. */
export const GLASS_COLORS = {
  dark: {
    accent: '#0067d9',
    accentForeground: '#ffffff',
    border: 'rgba(245, 245, 247, 0.22)',
    controlSurface: 'rgba(245, 245, 247, 0.08)',
    focusRing: '#b8b8be',
    foreground: '#f5f5f7',
    glassFill: { clear: 'rgba(255, 255, 255, 0.04)', tinted: 'rgba(28, 28, 30, 0.45)' },
    invalid: '#ff7a8e',
    knob: '#ffffff',
    mutedForeground: '#d1d1d6',
    opaqueSurface: '#2c2c2e',
    overlaySurface: 'rgba(44, 44, 46, 0.78)',
    rim: 'rgba(255, 255, 255, 0.16)',
    rimHighlight: 'rgba(255, 255, 255, 0.34)',
    scrim: 'rgba(0, 0, 0, 0.45)',
    shadow: '0px 1px 2px rgba(0, 0, 0, 0.18), 0px 8px 24px -4px rgba(0, 0, 0, 0.28)',
    shadowRaised: '0px 2px 6px rgba(0, 0, 0, 0.2), 0px 30px 60px -18px rgba(0, 0, 0, 0.55)',
    tones: {
      neutral: '#8e8e93',
      blue: '#78b7ff',
      green: '#33d69f',
      orange: '#ffbd38',
      red: '#ff5c7a',
      purple: '#9b80ff',
    },
    track: 'rgba(118, 118, 128, 0.36)',
  },
  light: {
    accent: '#0067d9',
    accentForeground: '#ffffff',
    border: 'rgba(0, 0, 0, 0.14)',
    controlSurface: 'rgba(255, 255, 255, 0.72)',
    focusRing: '#66666a',
    foreground: '#222224',
    glassFill: { clear: 'rgba(255, 255, 255, 0.18)', tinted: 'rgba(255, 255, 255, 0.55)' },
    invalid: '#c4153f',
    knob: '#ffffff',
    mutedForeground: '#505055',
    opaqueSurface: '#ffffff',
    overlaySurface: 'rgba(255, 255, 255, 0.82)',
    rim: 'rgba(255, 255, 255, 0.55)',
    rimHighlight: 'rgba(255, 255, 255, 0.9)',
    scrim: 'rgba(0, 0, 0, 0.16)',
    shadow: '0px 1px 2px rgba(0, 0, 0, 0.06), 0px 8px 24px -6px rgba(0, 0, 0, 0.14)',
    shadowRaised: '0px 2px 6px rgba(0, 0, 0, 0.06), 0px 28px 56px -18px rgba(0, 0, 0, 0.26)',
    tones: {
      neutral: '#8e8e93',
      blue: '#005ec6',
      green: '#14a874',
      orange: '#e8960c',
      red: '#e8345a',
      purple: '#6a4cf0',
    },
    track: 'rgba(118, 118, 128, 0.2)',
  },
} as const satisfies Record<GlassyUiTheme, GlassColors>;

export const GLASS_RADIUS = { md: 16, lg: 24, capsule: 999 } as const;

/** Arrivals ease out; physical responses spring and settle. Exits run shorter than arrivals. */
export const GLASS_MOTION = {
  duration: 200,
  /** React Native for Web has no native driver and warns when asked for one. */
  nativeDriver: Platform.OS !== 'web',
  spring: { damping: 18, mass: 1, stiffness: 260 },
} as const;

import { useCallback, useState } from 'react';

/**
 * State a component owns until its parent passes `value`; then the parent owns it. Either way
 * `onChange` hears every change the component makes.
 */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (next: T) => void,
) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const controlled = value !== undefined;
  const current = controlled ? value : uncontrolled;

  const setValue = useCallback(
    (next: T) => {
      if (!controlled) setUncontrolled(next);

      onChange?.(next);
    },
    [controlled, onChange],
  );

  return [current, setValue] as const;
}

import {
  Children,
  createContext,
  forwardRef,
  isValidElement,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import {
  Animated,
  Easing,
  StyleSheet,
  Text,
  View,
  type ImageSourcePropType,
  type ViewProps,
} from 'react-native';
import { useGlassTheme } from './glass-provider';
import { wrapPlainText } from './lib/plain-text';
import { GLASS_MOTION, type GlassTone } from './lib/tokens';

export type GlassAvatarSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

export type GlassAvatarStatus = 'online' | 'away' | 'busy' | 'offline';

export type GlassAvatarProps = Omit<ViewProps, 'children'> & {
  /** Describes the image. Defaults to `name`. */
  alt?: string;
  /** Shown when there is no image or it fails to load. Defaults to the initials of `name`. */
  fallback?: ReactNode;
  /** Names the person. Its initials fill in for a missing image and pick the colour. */
  name?: string;
  size?: GlassAvatarSize;
  /** A bundled image, as `require('./photo.jpg')` gives it. Use `src` for an address. */
  source?: ImageSourcePropType;
  /** The image's address. */
  src?: string;
  /** A presence dot on the corner. */
  status?: GlassAvatarStatus;
};

const SIZE = {
  xs: { diameter: 24, dot: 7 },
  sm: { diameter: 32, dot: 8 },
  md: { diameter: 40, dot: 10 },
  lg: { diameter: 56, dot: 14 },
  xl: { diameter: 80, dot: 18 },
} as const;

// Initials sit on one of these gradients, picked by the name so a person keeps their colour.
const TONES = [
  ['#2d6de9', '#1a4fc7'],
  ['#b93f24', '#882c1a'],
  ['#707075', '#56565b'],
  ['#d0386f', '#a82458'],
  ['#b9540f', '#9c4308'],
  ['#1f8150', '#146c3c'],
  ['#0e7d8b', '#0a6674'],
  ['#747479', '#535359'],
] as const;

// A face without a name is plain gray.
const NAMELESS = ['#747479', '#535359'] as const;

// The face's hairline rim and the light along its top.
const RIM = {
  dark: 'inset 0px 0px 0px 1px rgba(255, 255, 255, 0.18), inset 0px 1px 0px rgba(255, 255, 255, 0.22)',
  light: 'inset 0px 0px 0px 1px rgba(0, 0, 0, 0.1), inset 0px 1px 0px rgba(255, 255, 255, 0.3)',
} as const;

// The "+N" counter is a step brighter than a resting control.
const MORE_FILL = {
  dark: 'rgba(245, 245, 247, 0.14)',
  light: 'rgba(255, 255, 255, 0.95)',
} as const;

const STATUS_TONE = {
  away: 'orange',
  busy: 'red',
  offline: 'neutral',
  online: 'green',
} as const satisfies Record<GlassAvatarStatus, GlassTone>;

// The web cuts the face away around the dot and under the next avatar. React Native has no masks,
// so a ring in the surface colour draws that gap instead.
const GAP = 2;

const EASE_OUT = Easing.bezier(0.32, 0.72, 0, 1);

const GroupSizeContext = createContext<GlassAvatarSize | null>(null);

function initialsOf(name: string) {
  const words = name.trim().split(/\s+/).filter(Boolean);

  if (words.length === 0) return '';

  const first = Array.from(words[0])[0] ?? '';
  const last = words.length > 1 ? (Array.from(words[words.length - 1])[0] ?? '') : '';

  return `${first}${last}`.toUpperCase();
}

// The same name always gets the same colour.
function toneOf(name: string) {
  let hash = 0;

  for (const character of name) hash = (hash * 31 + (character.codePointAt(0) ?? 0)) >>> 0;

  return TONES[hash % TONES.length];
}

type FaceProps = {
  fallback: ReactNode;
  source: ImageSourcePropType | undefined;
  tone: readonly [string, string];
};

/** The image once it loads, over the fallback until then or for good if it fails. */
function Face({ fallback, source, tone }: FaceProps) {
  const { preferences } = useGlassTheme();
  const [status, setStatus] = useState<'loading' | 'loaded' | 'failed'>('loading');
  const [arrival] = useState(() => new Animated.Value(0));

  const handleLoad = useCallback(() => {
    setStatus('loaded');

    if (preferences.reduceMotion) {
      arrival.setValue(1);

      return;
    }

    Animated.timing(arrival, {
      duration: 260,
      easing: EASE_OUT,
      toValue: 1,
      useNativeDriver: GLASS_MOTION.nativeDriver,
    }).start();
  }, [arrival, preferences.reduceMotion]);

  const handleError = useCallback(() => setStatus('failed'), []);

  return (
    <>
      {status === 'loaded' ? null : (
        <View
          style={[
            StyleSheet.absoluteFill,
            styles.center,
            {
              backgroundColor: tone[0],
              experimental_backgroundImage: `linear-gradient(145deg, ${tone[0]}, ${tone[1]})`,
            },
          ]}
        >
          {fallback}
        </View>
      )}
      {source && status !== 'failed' ? (
        <Animated.Image
          accessibilityIgnoresInvertColors
          onError={handleError}
          onLoad={handleLoad}
          resizeMode="cover"
          source={source}
          style={[
            StyleSheet.absoluteFill,
            {
              opacity: arrival,
              transform: [
                { scale: arrival.interpolate({ inputRange: [0, 1], outputRange: [1.06, 1] }) },
              ],
            },
          ]}
        />
      ) : null}
    </>
  );
}

/** A round photo that falls back to coloured initials, with an optional presence dot. */
export const GlassAvatar = forwardRef<View, GlassAvatarProps>(
  ({ alt, fallback, name, size = 'md', source, src, status, style, ...rest }, ref) => {
    const { colors, preferences } = useGlassTheme();
    const groupSize = useContext(GroupSizeContext);
    const { diameter, dot } = SIZE[groupSize ?? size];
    const image = useMemo(() => source ?? (src ? { uri: src } : undefined), [source, src]);
    // A new image starts over, showing the fallback until it loads.
    const imageKey = image ? JSON.stringify(image) : 'none';
    const described = [alt ?? name, status].filter(Boolean).join(', ');
    // The dot's centre sits on the circle's edge, at its lower trailing corner.
    const center = diameter * 0.8536;

    const content = wrapPlainText(fallback ?? (name ? initialsOf(name) : null), (text) => (
      <Text style={[styles.initials, { fontSize: diameter * 0.38 }]}>{text}</Text>
    ));

    return (
      <View
        ref={ref}
        accessibilityLabel={described || undefined}
        accessibilityRole={described ? 'image' : undefined}
        accessible={described.length > 0}
        style={[{ height: diameter, width: diameter }, style]}
        {...rest}
      >
        <View
          accessibilityElementsHidden
          importantForAccessibility="no-hide-descendants"
          style={[
            styles.face,
            { backgroundColor: colors.controlSurface, borderRadius: diameter / 2 },
          ]}
        >
          <Face
            key={imageKey}
            fallback={content}
            source={image}
            tone={name ? toneOf(name) : NAMELESS}
          />
          <View
            style={[
              StyleSheet.absoluteFill,
              styles.rim,
              { borderRadius: diameter / 2, boxShadow: RIM[preferences.theme] },
            ]}
          />
        </View>
        {status ? (
          <View
            style={[
              styles.dot,
              {
                backgroundColor: colors.tones[STATUS_TONE[status]],
                borderColor: colors.opaqueSurface,
                borderRadius: dot / 2 + GAP,
                height: dot + GAP * 2,
                start: center - dot / 2 - GAP,
                top: center - dot / 2 - GAP,
                width: dot + GAP * 2,
              },
            ]}
          />
        ) : null}
      </View>
    );
  },
);

GlassAvatar.displayName = 'GlassAvatar';

export type GlassAvatarGroupProps = ViewProps & {
  /** Shows this many avatars, then a "+N" for the rest. */
  max?: number;
  /** Sizes every avatar in the group. */
  size?: GlassAvatarSize;
};

/** Avatars stacked edge to edge, each overlapping the one before it, then a "+N" for the rest. */
export const GlassAvatarGroup = forwardRef<View, GlassAvatarGroupProps>(
  ({ children, max, size = 'md', style, ...rest }, ref) => {
    const { colors, preferences } = useGlassTheme();
    const items = Children.toArray(children);
    const shown = max === undefined ? items : items.slice(0, Math.max(0, max));
    const hidden = items.length - shown.length;
    const { diameter } = SIZE[size];

    // Each avatar wears the gap ring outside its own outline, so the ring takes no room.
    const ring = {
      borderColor: colors.opaqueSurface,
      borderRadius: diameter / 2 + GAP,
      borderWidth: GAP,
      margin: -GAP,
    };

    const overlap = { marginStart: -diameter * 0.2 - GAP };

    return (
      <GroupSizeContext.Provider value={size}>
        <View ref={ref} style={[styles.group, style]} {...rest}>
          {shown.map((child, index) => (
            <View
              key={isValidElement(child) ? child.key : index}
              style={[ring, index > 0 && overlap]}
            >
              {child}
            </View>
          ))}
          {hidden > 0 ? (
            <View
              accessible
              accessibilityLabel={`${hidden} more`}
              accessibilityRole="image"
              style={[ring, shown.length > 0 && overlap]}
            >
              <View
                style={[
                  styles.face,
                  styles.center,
                  {
                    backgroundColor: MORE_FILL[preferences.theme],
                    borderRadius: diameter / 2,
                    height: diameter,
                    width: diameter,
                  },
                ]}
              >
                <Text
                  style={[styles.more, { color: colors.foreground, fontSize: diameter * 0.32 }]}
                >
                  +{hidden}
                </Text>
                <View
                  style={[
                    StyleSheet.absoluteFill,
                    styles.rim,
                    { borderRadius: diameter / 2, boxShadow: RIM[preferences.theme] },
                  ]}
                />
              </View>
            </View>
          ) : null}
        </View>
      </GroupSizeContext.Provider>
    );
  },
);

GlassAvatarGroup.displayName = 'GlassAvatarGroup';

const styles = StyleSheet.create({
  center: { alignItems: 'center', justifyContent: 'center' },
  dot: { borderWidth: GAP, pointerEvents: 'none', position: 'absolute' },
  face: { height: '100%', overflow: 'hidden', width: '100%' },
  group: { alignItems: 'center', flexDirection: 'row' },
  initials: {
    color: '#ffffff',
    fontWeight: '600',
    textShadowColor: 'rgba(0, 0, 0, 0.22)',
    textShadowOffset: { height: 1, width: 0 },
    textShadowRadius: 1,
  },
  more: { fontWeight: '600' },
  rim: { pointerEvents: 'none' },
});

import { Children, isValidElement, type ReactNode } from 'react';

/**
 * Sets plain text inside a Text, which React Native needs to render it. Content that is all text
 * becomes one Text; beside elements such as icons, each run of text gets its own.
 */
export function wrapPlainText(node: ReactNode, render: (text: ReactNode) => ReactNode) {
  const parts = Children.toArray(node);

  if (parts.length === 0) return null;

  if (parts.every((part) => !isValidElement(part))) return render(node);

  return Children.map(node, (part) => (isValidElement(part) ? part : render(part)));
}

/** The words in `node` when it is only text, to name a control for assistive technology. */
export function plainTextOf(node: ReactNode) {
  const parts = Children.toArray(node);

  return parts.length > 0 && parts.every((part) => !isValidElement(part))
    ? parts.join('')
    : undefined;
}
